function sec1_expect($fn,$status){try{$fn();throw new RuntimeException('Expected rejection');}catch(EIPSI_Rate_Limit_Exception $e){m0_assert($e->getCode()===$status,'Wrong rate status');return$e;}}
function sec1_csv($value){$s=fopen('php://temp','w+');EIPSI_Csv_Serializer::row($s,array($value));rewind($s);$out=fgetcsv($s,0,',','"','')[0];fclose($s);return$out;}
function sec1_wait($f){$end=microtime(true)+25;while(!file_exists($f)){if(basename($f)==='locked'&&is_file(dirname($f).'/result0.json'))throw new RuntimeException('Download worker: '.file_get_contents(dirname($f).'/result0.json'));if(microtime(true)>$end)throw new RuntimeException('Barrier timeout: '.basename($f));usleep(10000);}}
function sec1_spawn($dir,$i){$pipes=array();$p=proc_open(array(PHP_BINARY,__DIR__.'/sec1/worker.php',$dir,(string)$i),array(0=>array('pipe','r'),1=>array('file',$dir.'/stdout'.$i,'w'),2=>array('file',$dir.'/stderr'.$i,'w')),$pipes);m0_assert(is_resource($p),'Worker spawn');fclose($pipes[0]);return$p;}
function sec1_zip($zip,$wanted){$at=0;while(($at=strpos($zip,"PK\x01\x02",$at))!==false){$h=unpack('vmethod',substr($zip,$at+10,2));$size=unpack('Vn',substr($zip,$at+20,4))['n'];$n=unpack('vn',substr($zip,$at+28,2))['n'];$name=substr($zip,$at+46,$n);if($name===$wanted){$off=unpack('Vn',substr($zip,$at+42,4))['n'];$len=unpack('vn/ve',substr($zip,$off+26,4));$data=substr($zip,$off+30+$len['n']+$len['e'],$size);return$h['method']===8?gzinflate($data):$data;}$at+=46+$n;}throw new RuntimeException('ZIP entry missing');}
function sec1_job($expired=true){global$wpdb,$jobs;$id='MX_SEC1_'.bin2hex(random_bytes(8));$jobs[]=$id;$data=array('id'=>$id,'study_id'=>'SEC1_FIXTURE','actor_id'=>1,'request_id'=>$id,'state'=>'READY','created_at'=>gmdate('Y-m-d H:i:s',time()-7200),'expires_at'=>gmdate('Y-m-d H:i:s',time()+($expired?-60:3600)),'spec_json'=>'{"sensitive":"synthetic"}','plan_json'=>'["synthetic-plan"]','payload_json'=>'["synthetic-answer"]','manifest_json'=>'{"synthetic":true}');m0_assert($wpdb->insert($wpdb->prefix.'eipsi_engine_management_exports',$data)!==false,'Job fixture');return$id;}
