$tests['Logging excludes secrets answers payload and newline injection']=function(){$file=tempnam(sys_get_temp_dir(),'sec1-log-');$old=ini_get('error_log');ini_set('error_log',$file);try{EIPSI_Security_Log::event('SEC1_LOG_TEST',array('token'=>'SYNTHETIC_SECRET','email'=>'synthetic@example.invalid','answers'=>'RAW_SCIENTIFIC_ANSWER','Authorization'=>'Bearer SECRET','payload'=>str_repeat('HUGE_PAYLOAD',10000),'action'=>"spoof\nINJECTED",'code'=>'SAFE_CODE'));$log=file_get_contents($file);foreach(array('SYNTHETIC_SECRET','synthetic@example.invalid','RAW_SCIENTIFIC_ANSWER','HUGE_PAYLOAD','Bearer SECRET',"spoof\nINJECTED")as$s)m0_assert(strpos($log,$s)===false,'Sensitive log');m0_assert(strpos($log,'SAFE_CODE')!==false&&strlen($log)<1024,'Unbounded or missing structural log');}finally{ini_set('error_log',$old);unlink($file);}};
