$tests['Atomic rate below over independent and RetryAfter']=function(){$p=bin2hex(random_bytes(12));$now=time();m0_assert(EIPSI_Rate_Limiter::consume('sec1.limit',$p,2,60,$now)===1,'First count');m0_assert(EIPSI_Rate_Limiter::consume('sec1.limit',$p,2,60,$now)===2,'Second count');$e=sec1_expect(fn()=>EIPSI_Rate_Limiter::consume('sec1.limit',$p,2,60,$now),429);m0_assert($e->retry_after>0&&$e->retry_after<=60,'RetryAfter');m0_assert(EIPSI_Rate_Limiter::consume('sec1.limit',$p.'other',2,60,$now)===1,'Independent principal');m0_assert(EIPSI_Rate_Limiter::consume('sec1.other',$p,2,60,$now)===1,'Independent intent');};
