$tests['Rate storage failure is closed and retryable']=function(){global$wpdb;$filter=static function($sql){return strpos($sql,'INSERT IGNORE INTO '.$GLOBALS['wpdb']->options)!==false&&strpos($sql,EIPSI_Rate_Limiter::PREFIX)!==false?'SEC1_EXPECTED_SQL_FAILURE':$sql;};$old=$wpdb->suppress_errors(true);add_filter('query',$filter);try{$e=sec1_expect(fn()=>EIPSI_Rate_Limiter::consume('sec1.failure','synthetic',2,60),503);m0_assert($e->retry_after>0,'Missing retry on storage failure');}finally{remove_filter('query',$filter);$wpdb->suppress_errors($old);}$filter=static fn($sql)=>$sql==='SELECT LAST_INSERT_ID()'?'SEC1_EXPECTED_SELECT_FAILURE':$sql;$old=$wpdb->suppress_errors(true);add_filter('query',$filter);try{$e=sec1_expect(fn()=>EIPSI_Rate_Limiter::consume('sec1.failure.select','synthetic',2,60),503);m0_assert($e->retry_after>0,'Missing retry on result-read failure');}finally{remove_filter('query',$filter);$wpdb->suppress_errors($old);}};
$tests['Twenty concurrent requests admit exactly seven']=function(){$dir=sys_get_temp_dir().'/sec1-race-'.bin2hex(random_bytes(8));mkdir($dir);$processes=array();$start=microtime(true);file_put_contents($dir.'/input.json',wp_json_encode(array('mode'=>'rate','principal'=>bin2hex(random_bytes(16)),'now'=>time())));try{for($i=0;$i<20;$i++)$processes[$i]=sec1_spawn($dir,$i);for($i=0;$i<20;$i++)sec1_wait($dir.'/ready'.$i);touch($dir.'/start');$out=array();for($i=0;$i<20;$i++){sec1_wait($dir.'/result'.$i.'.json');$out[]=json_decode(file_get_contents($dir.'/result'.$i.'.json'),true);m0_assert(proc_close($processes[$i])===0,'Worker failed');unset($processes[$i]);}m0_assert(count(array_filter($out,fn($r)=>!empty($r['allowed'])))===7,'Lost increments or excessive admissions');echo 'SEC1 concurrency '.json_encode(array('requests'=>20,'admitted'=>7,'seconds'=>round(microtime(true)-$start,3)))."\n";}finally{touch($dir.'/start');foreach($processes as$p){proc_terminate($p);proc_close($p);}foreach(glob($dir.'/*')as$f)unlink($f);rmdir($dir);}};
