$tests['Cleanup races with real download without destroying its snapshot']=function(){
 global$wpdb,$jobs;require_once EIPSI_FORMS_PLUGIN_DIR.'includes/study-engine/content.php';require_once __DIR__.'/study-engine/cross-sectional/support.php';
 $p=pe_publish();$study=$p['definition']['study']['logical_id'];$q=new EIPSI\StudyEngine\Management\Query($study);$x=new EIPSI\StudyEngine\Management\Exports($q);$j=$x->create(array(),'responses','SEC1_RACE_'.bin2hex(random_bytes(8)));$j=$x->step($j['id']);$jobs[]=$j['id'];
 $raceStart=microtime(true);$dir=sys_get_temp_dir().'/sec1-download-'.bin2hex(random_bytes(8));mkdir($dir);$processes=array();file_put_contents($dir.'/input.json',wp_json_encode(array('mode'=>'download','study'=>$study,'job'=>$j['id'])));
 try{
  $processes[0]=sec1_spawn($dir,0);sec1_wait($dir.'/locked');
  file_put_contents($dir.'/input.json',wp_json_encode(array('mode'=>'cleanup')));$processes[1]=sec1_spawn($dir,1);sec1_wait($dir.'/cleanup_started');usleep(100000);touch($dir.'/release');
  foreach(array(0,1)as$i){sec1_wait($dir.'/result'.$i.'.json');m0_assert(proc_close($processes[$i])===0,'Export race worker failed');unset($processes[$i]);}
  $download=json_decode(file_get_contents($dir.'/result0.json'),true);$data=json_decode($download['content']??'',true);m0_assert(isset($data['manifest'])&&$data['rows']===array(),'Authorized download lost its captured snapshot');
  EIPSI\StudyEngine\Management\Exports::cleanup();m0_assert(!$wpdb->get_var($wpdb->prepare("SELECT id FROM {$wpdb->prefix}eipsi_engine_management_exports WHERE id=%s",$j['id'])),'Expired job survived race');
  m0_assert((int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}eipsi_engine_management_events WHERE entity_id=%s",$j['id']))>=2,'Minimal audit erased');echo 'SEC1 cleanup_race '.json_encode(array('seconds'=>round(microtime(true)-$raceStart,3),'download_preserved'=>true,'expired_payload_removed'=>true))."\n";
 }finally{touch($dir.'/release');foreach($processes as$process){proc_terminate($process);proc_close($process);}foreach(glob($dir.'/*')as$f)unlink($f);rmdir($dir);foreach(array('management_events','public_studies','study_versions')as$t)$wpdb->delete($wpdb->prefix.'eipsi_engine_'.$t,array('study_id'=>$study));}
};
