  $r=m0_http('/wp-admin/admin-ajax.php',array('action'=>'eipsi_native_participant','execution'=>$id,'payload'=>wp_json_encode($payload)),true);m0_assert(wp_remote_retrieve_response_code($r)===200,'Normal partial throttled: '.wp_remote_retrieve_body($r));$frame=json_decode(wp_remote_retrieve_body($r),true)['data'];
 }
 $after=$wpdb->get_results($wpdb->prepare("SELECT option_name,option_value FROM {$wpdb->options} WHERE option_name LIKE %s ORDER BY option_name",$wpdb->esc_like(EIPSI_Rate_Limiter::PREFIX).'%'),ARRAY_A);m0_assert($before===$after,'Per-answer budget writes');
 }finally{if($priorEnabled===null)delete_option('eipsi_native_runtime_enabled');else update_option('eipsi_native_runtime_enabled',$priorEnabled);_set_cron_array($priorCron);$wpdb->delete($wpdb->prefix.'eipsi_engine_native_commands',array('execution_id'=>$id));$wpdb->delete($wpdb->prefix.'eipsi_engine_native_executions',array('id'=>$id));$wpdb->delete($wpdb->prefix.'eipsi_engine_native_versions',array('id'=>$v['version_id']));delete_option(EIPSI\AssessmentEditor\Repository::PREFIX.$d['id']);}
